## Make changes releasable and operable

For a risky or cross-cutting change, decide:

- whether the contract can migrate compatibly and incrementally;
- whether a feature flag, staged rollout, or kill switch reduces meaningful risk;
- what can be rolled back independently;
- which failures need a local error boundary or recovery path;
- which production signals would reveal user harm;
- how logs, errors, traces, analytics, and source maps avoid secrets and personal
  data;
- which field metrics and representative segments matter.

Telemetry should answer a decision or detect a failure. Do not add events merely
because an interaction exists. Use stable event semantics, sampling where
appropriate, and project privacy rules. Lab profiling diagnoses controlled
conditions; field data shows what real users experienced.

Keep implementation increments reviewable and reversible. Do not enforce a
universal line or file limit, but separate preparatory refactoring, contract
changes, and feature behavior when independent review or rollback would be
materially safer.

{
  "name": "frontend-architect-vite-plugin-eval",
  "private": true,
  "type": "module",
  "workspaces": [
    "packages/*",
    "examples/*"
  ],
  "scripts": {
    "build:plugin": "npm run build --workspace @frontend-architect-eval/feature-flags",
    "typecheck": "tsc -p packages/plugin/tsconfig.json --noEmit && tsc -p examples/consumer/tsconfig.json --noEmit",
    "test:build": "vite build --config examples/consumer/vite.config.ts && node scripts/check-build.mjs",
    "test:dev": "node scripts/check-dev.mjs",
    "test:diagnostics": "node scripts/check-diagnostics.mjs",
    "test:package": "node scripts/check-package.mjs",
    "check": "npm run build:plugin && npm run typecheck && npm run test:build && npm run test:dev && npm run test:diagnostics && npm run test:package"
  },
  "devDependencies": {
    "@types/node": "26.2.0",
    "typescript": "5.9.2",
    "vite": "8.2.2"
  }
}

{
  "extends": "./tsconfig.json",
  "compilerOptions": {
    "outDir": "dist",
    "rootDir": "src",
    "declaration": true,
    "declarationMap": true,
    "sourceMap": true
  }
}

{
  "compilerOptions": {
    "target": "ES2022",
    "module": "NodeNext",
    "moduleResolution": "NodeNext",
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "exactOptionalPropertyTypes": true,
    "types": ["node"]
  },
  "include": ["src/**/*.ts"]
}

declare module 'virtual:feature-flags' {
  export type FeatureFlagValue = boolean | number | string
  export const flags: Readonly<Record<string, FeatureFlagValue>>
}

import type { Plugin } from 'vite'

export function featureFlags(flags: Record<string, unknown>): Plugin {
  return {
    name: 'feature-flags',
    transform(code: string) {
      return code.replaceAll('__FLAGS__', JSON.stringify(flags))
    },
  }
}

import { fileURLToPath } from 'node:url'

import { featureFlags } from '@frontend-architect-eval/feature-flags'
import { defineConfig } from 'vite'

const root = fileURLToPath(new URL('.', import.meta.url))

export default defineConfig({
  root,
  plugins: [
    featureFlags({
      source: new URL('./flags.json', import.meta.url),
      expose: ['checkoutV2', 'theme'],
    }),
  ],
  build: {
    outDir: 'dist',
    emptyOutDir: true,
    sourcemap: true,
  },
})

{
  "name": "@frontend-architect-eval/feature-flags-consumer",
  "private": true,
  "type": "module",
  "dependencies": {
    "@frontend-architect-eval/feature-flags": "0.0.0"
  }
}

{
  "name": "@frontend-architect-eval/feature-flags",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "files": [
    "dist"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./virtual": {
      "types": "./dist/virtual.d.ts",
      "import": "./dist/empty.js"
    }
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json && node scripts/copy-static.mjs"
  },
  "peerDependencies": {
    "vite": "^8.0.0"
  }
}

{
  "checkoutV2": true,
  "theme": "dark",
  "SERVER_TOKEN": "server-token-for-eval"
}

{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "Bundler",
    "strict": true,
    "noEmit": true,
    "types": ["@frontend-architect-eval/feature-flags/virtual"]
  },
  "include": ["src/**/*.ts", "vite.config.ts"]
}

import { flags } from './flags'

const root = document.querySelector<HTMLElement>('#app')

if (root) {
  root.textContent = `${String(flags.checkoutV2)}:${String(flags.theme)}`
}

import assert from 'node:assert/strict'
import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

import { featureFlags } from '../packages/plugin/dist/index.js'
import { createServer } from 'vite'

const root = fileURLToPath(new URL('../examples/consumer/', import.meta.url))
const source = fileURLToPath(new URL('../examples/consumer/flags.json', import.meta.url))
const original = await readFile(source, 'utf8')
const server = await createServer({
  root,
  configFile: false,
  logLevel: 'silent',
  server: { middlewareMode: true },
  plugins: [featureFlags({ source, expose: ['checkoutV2', 'theme'] })],
})

try {
  const first = await server.ssrLoadModule('/src/flags.ts')
  assert.deepEqual(first.flags, { checkoutV2: true, theme: 'dark' })

  const changed = JSON.stringify({
    checkoutV2: false,
    theme: 'light',
    SERVER_TOKEN: 'server-token-for-eval',
  })
  const changeSeen = new Promise((resolve) => server.watcher.once('change', resolve))
  await writeFile(source, changed)
  await changeSeen

  const deadline = Date.now() + 2_000
  let updated
  do {
    updated = await server.ssrLoadModule('/src/flags.ts')
    if (updated.flags.checkoutV2 === false) break
    await new Promise((resolve) => setTimeout(resolve, 25))
  } while (Date.now() < deadline)

  assert.deepEqual(updated.flags, { checkoutV2: false, theme: 'light' })
  assert.doesNotMatch(JSON.stringify(updated.flags), /server-token-for-eval/)
} finally {
  await writeFile(source, original)
  await server.close()
}

import assert from 'node:assert/strict'
import { fileURLToPath } from 'node:url'

import { featureFlags } from '../packages/plugin/dist/index.js'
import { build } from 'vite'

const root = fileURLToPath(new URL('../examples/consumer/', import.meta.url))
const source = fileURLToPath(new URL('../examples/consumer/flags.json', import.meta.url))

await assert.rejects(
  build({
    root,
    configFile: false,
    logLevel: 'silent',
    plugins: [featureFlags({ source, expose: ['missingFlag'] })],
    build: { write: false },
  }),
  (error) => {
    const message = error instanceof Error ? error.message : String(error)
    return message.includes('missingFlag') && message.includes('flags.json')
  },
)

import assert from 'node:assert/strict'
import { readdir, readFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

const dist = fileURLToPath(new URL('../examples/consumer/dist/', import.meta.url))
const assets = await readdir(new URL('assets/', `file://${dist}/`))
const scripts = await Promise.all(
  assets.filter((name) => name.endsWith('.js')).map((name) => readFile(`${dist}/assets/${name}`, 'utf8')),
)
const bundle = scripts.join('\n')
const sourceMaps = await Promise.all(
  assets.filter((name) => name.endsWith('.map')).map((name) => readFile(`${dist}/assets/${name}`, 'utf8')),
)
const clientArtifacts = [...scripts, ...sourceMaps].join('\n')

assert.match(bundle, /checkoutV2/)
assert.doesNotMatch(clientArtifacts, /server-token-for-eval/)

